import type { Model } from '@wener/ai/schema';
import type { ComponentPropsWithRef } from 'react';
import type {
	AiConfigEditorOption,
	AiConfigEditorSlots,
	AiConfigSchema,
	AiConfigValidationMode,
	AiResourceEditorMessageOverrides,
	AiResourceEditorMessages,
} from '../../ui/ai-config-editor';

export type AiModelEditorField =
	| 'id'
	| 'name'
	| 'title'
	| 'description'
	| 'providerId'
	| 'endpointId'
	| 'endpointKey'
	| 'type'
	| 'family'
	| 'apiType'
	| 'contextWindow'
	| 'maxInputTokens'
	| 'maxOutputTokens'
	| 'modalities'
	| 'capabilities'
	| 'limits'
	| 'cost'
	| 'defaults'
	| 'status'
	| 'releaseDate'
	| 'knowledge'
	| 'openWeights'
	| 'headers'
	| 'tags'
	| 'labels'
	| 'options'
	| 'extensions'
	| 'enabled';
export type AiModelEditorSection =
	| 'identity'
	| 'binding'
	| 'limits'
	| 'modalities'
	| 'capabilities'
	| 'costDefaults'
	| 'metadata';
export type AiModelEditorMessages = AiResourceEditorMessages<AiModelEditorField, AiModelEditorSection>;
export type AiModelEditorMessageOverrides = AiResourceEditorMessageOverrides<AiModelEditorField, AiModelEditorSection>;

export type AiModelEditorProps = Omit<ComponentPropsWithRef<'div'>, 'onChange' | 'title'> & {
	value: Model;
	onChange: (value: Model) => void;
	onSubmit?: (value: Model) => void;
	schema?: AiConfigSchema<Model>;
	validationMode?: AiConfigValidationMode;
	disabled?: boolean;
	readOnly?: boolean;
	messages?: AiModelEditorMessageOverrides;
	slots?: AiConfigEditorSlots<Model>;
	providerOptions?: readonly AiConfigEditorOption[];
	endpointOptions?: readonly AiConfigEditorOption[];
	apiTypeOptions?: readonly AiConfigEditorOption[];
};

import type { Model, ModelCapabilities, ModelCost, ModelDefaults, ModelLimits } from '@wener/ai/schema';
import {
	type AiConfigEditorSlots,
	AiConfigFieldGrid,
	AiConfigNumberField,
	AiConfigTextField,
	AiConfigToggleField,
} from '../../ui/ai-config-editor';

const capabilityFields: readonly { key: keyof Omit<ModelCapabilities, 'extensions'>; label: string }[] = [
	{ key: 'messageGeneration', label: '消息生成' },
	{ key: 'textCompletion', label: '文本补全' },
	{ key: 'embedding', label: '向量嵌入' },
	{ key: 'imageGeneration', label: '图像生成' },
	{ key: 'imageEditing', label: '图像编辑' },
	{ key: 'reranking', label: '重排序' },
	{ key: 'tokenCounting', label: 'Token 计数' },
	{ key: 'reasoning', label: 'Reasoning' },
	{ key: 'toolCall', label: '工具调用' },
	{ key: 'attachment', label: '附件' },
	{ key: 'temperature', label: 'Temperature' },
	{ key: 'structuredOutput', label: '结构化输出' },
	{ key: 'jsonSchema', label: 'JSON Schema' },
	{ key: 'jsonObject', label: 'JSON Object' },
];

export type AiModelAdvancedFieldsProps = {
	value: Model;
	onChange: (value: Model) => void;
	disabled?: boolean;
	readOnly?: boolean;
	slots?: AiConfigEditorSlots<Model>;
};

export function AiModelCapabilitiesFields({
	value,
	onChange,
	disabled = false,
	readOnly = false,
}: AiModelAdvancedFieldsProps) {
	const capabilities = value.capabilities ?? {};
	const update = (key: keyof Omit<ModelCapabilities, 'extensions'>, enabled: boolean) =>
		onChange({ ...value, capabilities: { ...capabilities, [key]: enabled } });
	return (
		<AiConfigFieldGrid className='lg:grid-cols-3'>
			{capabilityFields.map(({ key, label }) => (
				<AiConfigToggleField
					key={key}
					label={label}
					checked={capabilities[key] ?? false}
					disabled={disabled || readOnly}
					onCheckedChange={(enabled) => update(key, enabled)}
				/>
			))}
		</AiConfigFieldGrid>
	);
}

export function AiModelLimitFields({
	value,
	onChange,
	disabled = false,
	readOnly = false,
}: AiModelAdvancedFieldsProps) {
	const limits = value.limits ?? {};
	const update = (patch: Partial<ModelLimits>) => onChange({ ...value, limits: { ...limits, ...patch } });
	return (
		<AiConfigFieldGrid>
			<AiConfigNumberField
				label='限制 · Context'
				value={limits.context}
				integer
				min={1}
				disabled={disabled}
				readOnly={readOnly}
				onValueChange={(context) => update({ context })}
			/>
			<AiConfigNumberField
				label='限制 · Input'
				value={limits.input}
				integer
				min={1}
				disabled={disabled}
				readOnly={readOnly}
				onValueChange={(input) => update({ input })}
			/>
			<AiConfigNumberField
				label='限制 · Output'
				value={limits.output}
				integer
				min={1}
				disabled={disabled}
				readOnly={readOnly}
				onValueChange={(output) => update({ output })}
			/>
			<AiConfigNumberField
				label='每分钟请求'
				value={limits.requestsPerMinute}
				integer
				min={1}
				disabled={disabled}
				readOnly={readOnly}
				onValueChange={(requestsPerMinute) => update({ requestsPerMinute })}
			/>
			<AiConfigNumberField
				label='每分钟 Token'
				value={limits.tokensPerMinute}
				integer
				min={1}
				disabled={disabled}
				readOnly={readOnly}
				onValueChange={(tokensPerMinute) => update({ tokensPerMinute })}
			/>
		</AiConfigFieldGrid>
	);
}

export function AiModelCostDefaultFields({
	value,
	onChange,
	disabled = false,
	readOnly = false,
}: AiModelAdvancedFieldsProps) {
	const cost = value.cost ?? {};
	const defaults = value.defaults ?? {};
	const updateCost = (patch: Partial<ModelCost>) => onChange({ ...value, cost: { ...cost, ...patch } });
	const updateDefaults = (patch: Partial<ModelDefaults>) => onChange({ ...value, defaults: { ...defaults, ...patch } });
	return (
		<div className='grid min-w-0 gap-6 xl:grid-cols-2'>
			<div>
				<h4 className='mb-3 text-xs font-semibold'>成本</h4>
				<AiConfigFieldGrid>
					<AiConfigNumberField
						label='输入成本'
						value={cost.input}
						min={0}
						disabled={disabled}
						readOnly={readOnly}
						onValueChange={(input) => updateCost({ input })}
					/>
					<AiConfigNumberField
						label='输出成本'
						value={cost.output}
						min={0}
						disabled={disabled}
						readOnly={readOnly}
						onValueChange={(output) => updateCost({ output })}
					/>
					<AiConfigNumberField
						label='缓存读取成本'
						value={cost.cacheRead}
						min={0}
						disabled={disabled}
						readOnly={readOnly}
						onValueChange={(cacheRead) => updateCost({ cacheRead })}
					/>
					<AiConfigNumberField
						label='缓存写入成本'
						value={cost.cacheWrite}
						min={0}
						disabled={disabled}
						readOnly={readOnly}
						onValueChange={(cacheWrite) => updateCost({ cacheWrite })}
					/>
					<AiConfigNumberField
						label='Reasoning 成本'
						value={cost.reasoning}
						min={0}
						disabled={disabled}
						readOnly={readOnly}
						onValueChange={(reasoning) => updateCost({ reasoning })}
					/>
					<AiConfigTextField
						label='币种'
						value={cost.currency}
						placeholder='USD'
						disabled={disabled}
						readOnly={readOnly}
						onValueChange={(currency) => updateCost({ currency: optional(currency) })}
					/>
					<AiConfigTextField
						label='成本单位'
						value={cost.unit}
						placeholder='1M tokens'
						disabled={disabled}
						readOnly={readOnly}
						onValueChange={(unit) => updateCost({ unit: optional(unit) })}
					/>
				</AiConfigFieldGrid>
			</div>
			<div>
				<h4 className='mb-3 text-xs font-semibold'>默认推理参数</h4>
				<AiConfigFieldGrid>
					<AiConfigNumberField
						label='Temperature'
						value={defaults.temperature}
						disabled={disabled}
						readOnly={readOnly}
						onValueChange={(temperature) => updateDefaults({ temperature })}
					/>
					<AiConfigNumberField
						label='Top P'
						value={defaults.topP}
						disabled={disabled}
						readOnly={readOnly}
						onValueChange={(topP) => updateDefaults({ topP })}
					/>
					<AiConfigNumberField
						label='Top K'
						value={defaults.topK}
						disabled={disabled}
						readOnly={readOnly}
						onValueChange={(topK) => updateDefaults({ topK })}
					/>
					<AiConfigNumberField
						label='Max Tokens'
						value={defaults.maxTokens}
						integer
						min={1}
						disabled={disabled}
						readOnly={readOnly}
						onValueChange={(maxTokens) => updateDefaults({ maxTokens })}
					/>
					<AiConfigNumberField
						label='Frequency Penalty'
						value={defaults.frequencyPenalty}
						disabled={disabled}
						readOnly={readOnly}
						onValueChange={(frequencyPenalty) => updateDefaults({ frequencyPenalty })}
					/>
					<AiConfigNumberField
						label='Presence Penalty'
						value={defaults.presencePenalty}
						disabled={disabled}
						readOnly={readOnly}
						onValueChange={(presencePenalty) => updateDefaults({ presencePenalty })}
					/>
				</AiConfigFieldGrid>
			</div>
		</div>
	);
}

function optional(value: string): string | undefined {
	return value.trim() ? value : undefined;
}

'use client';

import { DefaultApiRegistry, type Model, ModelSchema } from '@wener/ai/schema';
import type { ReactNode } from 'react';
import {
	AiConfigEditor,
	AiConfigFieldGrid,
	AiConfigFieldSlot,
	AiConfigFormSection,
	AiConfigKeyValueField,
	AiConfigNumberField,
	AiConfigSelectField,
	AiConfigStringListField,
	AiConfigTextareaField,
	AiConfigTextField,
	AiConfigToggleField,
	aiConfigFieldError,
	JsonValueEditor,
	mergeResourceEditorMessages,
	useAiConfigDraft,
} from '../../ui/ai-config-editor';
import { AiModelCapabilitiesFields, AiModelCostDefaultFields, AiModelLimitFields } from './ai-model-advanced-fields';
import type { AiModelEditorField, AiModelEditorMessages, AiModelEditorProps } from './ai-model-editor-types';

export const defaultAiModel: Model = ModelSchema.parse({
	id: 'model-new',
	name: 'model-new',
	type: 'chat',
	enabled: true,
});
const apiTypes = DefaultApiRegistry.apiTypes.map((item) => ({ value: item.name, label: item.name }));
const families = DefaultApiRegistry.families.map((item) => ({ value: item.name, label: item.name }));
const modelTypes = ['chat', 'completion', 'embedding', 'rerank', 'generation', 'image', 'audio', 'video'].map(
	(value) => ({ value, label: value }),
);
const statuses = ['alpha', 'beta', 'active', 'deprecated', 'disabled'].map((value) => ({ value, label: value }));

const defaultMessages: AiModelEditorMessages = {
	title: 'AI Model 配置',
	description: '绑定 Provider/Endpoint，并配置模型能力、限制、成本和默认参数。',
	sections: {
		identity: '身份',
		binding: 'Provider 与 API 绑定',
		limits: '上下文与 Token 限制',
		modalities: '输入输出模态',
		capabilities: '能力',
		costDefaults: '成本与默认参数',
		metadata: '状态、标签与扩展',
	},
	fields: {
		id: 'ID',
		name: '名称',
		title: '显示名称',
		description: '描述',
		providerId: 'Provider',
		endpointId: 'Endpoint',
		endpointKey: 'Endpoint Key',
		type: '模型类型',
		family: 'API Family',
		apiType: 'API 类型',
		contextWindow: 'Context Window',
		maxInputTokens: '最大输入 Token',
		maxOutputTokens: '最大输出 Token',
		modalities: '模态',
		capabilities: '能力',
		limits: '高级限制',
		cost: '成本',
		defaults: '默认参数',
		status: '状态',
		releaseDate: '发布日期',
		knowledge: '知识截止/说明',
		openWeights: '开放权重',
		headers: '请求头',
		tags: '标签',
		labels: 'Labels',
		options: 'Options',
		extensions: 'Extensions',
		enabled: '启用 Model',
	},
};

export function AiModelEditor({
	value,
	onChange,
	onSubmit,
	schema = ModelSchema,
	validationMode,
	disabled = false,
	readOnly = false,
	messages: overrides,
	slots,
	providerOptions = [],
	endpointOptions = [],
	apiTypeOptions = apiTypes,
	...props
}: AiModelEditorProps) {
	const messages = mergeResourceEditorMessages(defaultMessages, overrides);
	const controller = useAiConfigDraft({
		value,
		fallbackValue: defaultAiModel,
		schema,
		onChange,
		onSubmit,
		validationMode,
	});
	const draft = controller.draft;
	const locked = disabled || readOnly;
	const patch = (next: Partial<Model>) => controller.setDraft({ ...draft, ...next });
	const field = (name: AiModelEditorField, defaultField: ReactNode) => (
		<AiConfigFieldSlot
			name={name}
			draft={draft}
			disabled={disabled}
			readOnly={readOnly}
			error={aiConfigFieldError(controller.visibleIssues, name)}
			defaultField={defaultField}
			onDraftChange={controller.setDraft}
			slots={slots}
		/>
	);
	return (
		<AiConfigEditor
			{...props}
			title={messages.title}
			description={messages.description}
			controller={controller}
			messages={messages.editor}
			slots={slots}
			disabled={disabled}
			readOnly={readOnly}
			showSubmit={Boolean(onSubmit)}
		>
			<AiConfigFormSection title={messages.sections.identity}>
				<AiConfigFieldGrid>
					{field(
						'id',
						<AiConfigTextField
							required
							label={messages.fields.id}
							value={draft.id}
							error={aiConfigFieldError(controller.visibleIssues, 'id')}
							disabled={disabled}
							readOnly={readOnly}
							onValueChange={(id) => patch({ id })}
						/>,
					)}
					{field(
						'name',
						<AiConfigTextField
							required
							label={messages.fields.name}
							value={draft.name}
							error={aiConfigFieldError(controller.visibleIssues, 'name')}
							disabled={disabled}
							readOnly={readOnly}
							onValueChange={(name) => patch({ name })}
						/>,
					)}
					{field(
						'title',
						<AiConfigTextField
							label={messages.fields.title}
							value={draft.title}
							disabled={disabled}
							readOnly={readOnly}
							onValueChange={(title) => patch({ title: optional(title) })}
						/>,
					)}
					{field(
						'type',
						<AiConfigSelectField
							label={messages.fields.type}
							value={draft.type}
							options={modelTypes}
							disabled={locked}
							onValueChange={(type) => patch({ type: type ? (type as Model['type']) : undefined })}
						/>,
					)}
				</AiConfigFieldGrid>
				{field(
					'description',
					<AiConfigTextareaField
						wrapperClassName='mt-4'
						label={messages.fields.description}
						value={draft.description}
						disabled={disabled}
						readOnly={readOnly}
						onValueChange={(description) => patch({ description: optional(description) })}
					/>,
				)}
			</AiConfigFormSection>
			<AiConfigFormSection title={messages.sections.binding}>
				<AiConfigFieldGrid>
					{field(
						'providerId',
						<AiConfigSelectField
							label={messages.fields.providerId}
							value={draft.providerId}
							options={providerOptions}
							disabled={locked}
							onValueChange={(providerId) => patch({ providerId: optional(providerId) })}
						/>,
					)}
					{field(
						'endpointId',
						<AiConfigSelectField
							label={messages.fields.endpointId}
							value={draft.endpointId}
							options={endpointOptions}
							disabled={locked}
							onValueChange={(endpointId) => patch({ endpointId: optional(endpointId) })}
						/>,
					)}
					{field(
						'endpointKey',
						<AiConfigTextField
							label={messages.fields.endpointKey}
							value={draft.endpointKey}
							disabled={disabled}
							readOnly={readOnly}
							onValueChange={(endpointKey) => patch({ endpointKey: optional(endpointKey) })}
						/>,
					)}
					{field(
						'family',
						<AiConfigSelectField
							label={messages.fields.family}
							value={draft.family}
							options={families}
							disabled={locked}
							onValueChange={(family) => patch({ family: optional(family) })}
						/>,
					)}
					{field(
						'apiType',
						<AiConfigSelectField
							label={messages.fields.apiType}
							value={draft.apiType}
							options={apiTypeOptions}
							disabled={locked}
							onValueChange={(apiType) => patch({ apiType: optional(apiType) })}
						/>,
					)}
				</AiConfigFieldGrid>
			</AiConfigFormSection>
			<AiConfigFormSection title={messages.sections.limits}>
				<AiConfigFieldGrid>
					{field(
						'contextWindow',
						<AiConfigNumberField
							label={messages.fields.contextWindow}
							value={draft.contextWindow}
							integer
							min={1}
							disabled={disabled}
							readOnly={readOnly}
							onValueChange={(contextWindow) => patch({ contextWindow })}
						/>,
					)}
					{field(
						'maxInputTokens',
						<AiConfigNumberField
							label={messages.fields.maxInputTokens}
							value={draft.maxInputTokens}
							integer
							min={1}
							disabled={disabled}
							readOnly={readOnly}
							onValueChange={(maxInputTokens) => patch({ maxInputTokens })}
						/>,
					)}
					{field(
						'maxOutputTokens',
						<AiConfigNumberField
							label={messages.fields.maxOutputTokens}
							value={draft.maxOutputTokens}
							integer
							min={1}
							disabled={disabled}
							readOnly={readOnly}
							onValueChange={(maxOutputTokens) => patch({ maxOutputTokens })}
						/>,
					)}
				</AiConfigFieldGrid>
				<div className='mt-4'>
					{field(
						'limits',
						<AiModelLimitFields value={draft} onChange={controller.setDraft} disabled={disabled} readOnly={readOnly} />,
					)}
				</div>
			</AiConfigFormSection>
			<AiConfigFormSection title={messages.sections.modalities}>
				<div className='grid gap-4 lg:grid-cols-2'>
					{field(
						'modalities',
						<AiConfigStringListField
							label='输入模态'
							value={draft.modalities?.input ?? []}
							disabled={disabled}
							readOnly={readOnly}
							onChange={(input) => patch({ modalities: { ...draft.modalities, input } })}
						/>,
					)}
					<AiConfigStringListField
						label='输出模态'
						value={draft.modalities?.output ?? []}
						disabled={disabled}
						readOnly={readOnly}
						onChange={(output) => patch({ modalities: { ...draft.modalities, output } })}
					/>
				</div>
			</AiConfigFormSection>
			<AiConfigFormSection title={messages.sections.capabilities}>
				{field(
					'capabilities',
					<AiModelCapabilitiesFields
						value={draft}
						onChange={controller.setDraft}
						disabled={disabled}
						readOnly={readOnly}
					/>,
				)}
			</AiConfigFormSection>
			<AiConfigFormSection title={messages.sections.costDefaults}>
				{field(
					'cost',
					<AiModelCostDefaultFields
						value={draft}
						onChange={controller.setDraft}
						disabled={disabled}
						readOnly={readOnly}
					/>,
				)}
			</AiConfigFormSection>
			<AiConfigFormSection title={messages.sections.metadata}>
				<AiConfigFieldGrid>
					{field(
						'status',
						<AiConfigSelectField
							label={messages.fields.status}
							value={draft.status}
							options={statuses}
							disabled={locked}
							onValueChange={(status) => patch({ status: status ? (status as Model['status']) : undefined })}
						/>,
					)}
					{field(
						'releaseDate',
						<AiConfigTextField
							type='date'
							label={messages.fields.releaseDate}
							value={draft.releaseDate}
							disabled={disabled}
							readOnly={readOnly}
							onValueChange={(releaseDate) => patch({ releaseDate: optional(releaseDate) })}
						/>,
					)}
					{field(
						'knowledge',
						<AiConfigTextField
							label={messages.fields.knowledge}
							value={draft.knowledge}
							disabled={disabled}
							readOnly={readOnly}
							onValueChange={(knowledge) => patch({ knowledge: optional(knowledge) })}
						/>,
					)}
					{field(
						'openWeights',
						<AiConfigToggleField
							label={messages.fields.openWeights}
							checked={draft.openWeights ?? false}
							disabled={locked}
							onCheckedChange={(openWeights) => patch({ openWeights })}
						/>,
					)}
				</AiConfigFieldGrid>
				<div className='mt-4 grid gap-4 lg:grid-cols-2'>
					{field(
						'headers',
						<AiConfigKeyValueField
							label={messages.fields.headers}
							value={draft.headers}
							disabled={disabled}
							readOnly={readOnly}
							onChange={(headers) => patch({ headers })}
						/>,
					)}
					{field(
						'labels',
						<AiConfigKeyValueField
							label={messages.fields.labels}
							value={draft.labels}
							disabled={disabled}
							readOnly={readOnly}
							onChange={(labels) => patch({ labels })}
						/>,
					)}
				</div>
				{field(
					'tags',
					<AiConfigStringListField
						className='mt-4'
						label={messages.fields.tags}
						value={draft.tags}
						disabled={disabled}
						readOnly={readOnly}
						onChange={(tags) => patch({ tags })}
					/>,
				)}
				<div className='mt-4 grid gap-4 lg:grid-cols-2'>
					{field(
						'options',
						<JsonValueEditor
							label={messages.fields.options}
							value={draft.options ?? {}}
							disabled={disabled}
							readOnly={readOnly}
							onChange={(options) => patch({ options: options as Model['options'] })}
						/>,
					)}
					{field(
						'extensions',
						<JsonValueEditor
							label={messages.fields.extensions}
							value={draft.extensions ?? {}}
							disabled={disabled}
							readOnly={readOnly}
							onChange={(extensions) => patch({ extensions: extensions as Model['extensions'] })}
						/>,
					)}
				</div>
				{field(
					'enabled',
					<AiConfigToggleField
						wrapperClassName='mt-4'
						label={messages.fields.enabled}
						checked={draft.enabled ?? true}
						disabled={locked}
						onCheckedChange={(enabled) => patch({ enabled })}
					/>,
				)}
			</AiConfigFormSection>
		</AiConfigEditor>
	);
}

function optional(value: string): string | undefined {
	return value.trim() ? value : undefined;
}

export * from './ai-model-advanced-fields';
export * from './ai-model-editor';
export * from './ai-model-editor-types';
